enum MyOption {
  Some(value: Int),
  None,
}

fn find_score(name: Str) -> MyOption {
  if name == "Alice" {
    return MyOption.Some(95);
  }
  if name == "Bob" {
    return MyOption.Some(88);
  }
  return MyOption.None;
}

fn describe_result(option: MyOption) {
  match option {
    Some(value) => io.println(value),
    None => io.println("No score found"),
  }
}

fn main() -> Int {
  let r1 = find_score("Alice");
  let r2 = find_score("Charlie");
  let r3 = find_score("Bob");
  describe_result(r1);
  describe_result(r2);
  describe_result(r3);
  return 0;
}
